import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/models.dart';
import '../services/storage_service.dart';
import '../widgets/app_card.dart';

const expenseCategories = ['Alimentação', 'Transporte', 'Moradia', 'Lazer', 'Educação', 'Saúde', 'Compras', 'Outros'];
const incomeCategories = ['Salário', 'Freelance', 'Investimentos', 'Outros'];

class FinanceScreen extends StatefulWidget {
  const FinanceScreen({super.key});
  @override State<FinanceScreen> createState() => _FinanceScreenState();
}

class _FinanceScreenState extends State<FinanceScreen> {
  List<MoneyTransaction> items = [];
  DateTime month = DateTime(DateTime.now().year, DateTime.now().month);
  bool loading = true;
  String view = 'consolidada';

  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async { items = (await StorageService.read('finance')).map(MoneyTransaction.fromJson).toList(); _refreshStatuses(); loading = false; if (mounted) setState(() {}); }
  void _refreshStatuses() { final today = DateTime.now(); for (final x in items) { if (!x.isPaid && !x.isCancelled) { final d = DateTime.tryParse(x.dueDate); if (d != null && DateTime(d.year,d.month,d.day).isBefore(DateTime(today.year,today.month,today.day))) x.paymentStatus = 'overdue'; } } }
  Future<void> _save() => StorageService.write('finance', items.map((e) => e.toJson()).toList());
  String _key(DateTime d) => DateFormat('yyyy-MM').format(d);
  String _money(double v) => 'R\$ ${v.toStringAsFixed(2).replaceAll('.', ',')}';
  bool _inMonth(MoneyTransaction x, DateTime m) => x.date.startsWith(_key(m));
  Iterable<MoneyTransaction> get selected => items.where((x) => _inMonth(x, month) && !x.isCancelled);
  double _sum(Iterable<MoneyTransaction> xs, bool income, {bool onlyPaid = false}) => xs.where((x) => x.income == income && (!onlyPaid || x.isPaid)).fold(0.0, (s,x) => s + x.amount);
  double _forecastIncome(DateTime m) => items.where((x) => _inMonth(x,m) && x.income && !x.isCancelled).fold(0.0,(s,x)=>s+x.amount);
  double _forecastExpenses(DateTime m) => items.where((x) => _inMonth(x,m) && !x.income && !x.isCancelled).fold(0.0,(s,x)=>s+x.amount);
  double _committed(DateTime m) => items.where((x) => _inMonth(x,m) && !x.income && !x.isCancelled && !x.isPaid).fold(0.0,(s,x)=>s+x.amount);
  double _actualBalance() => items.where((x)=>x.isPaid && !x.isCancelled).fold(0.0,(s,x)=>s+(x.income?x.amount:-x.amount));

  Future<void> _add() async {
    final result = await showModalBottomSheet<String>(context: context, builder: (ctx) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: [ListTile(leading: const Icon(Icons.add_circle_outline), title: const Text('Pagamento único'), onTap: ()=>Navigator.pop(ctx,'single')), ListTile(leading: const Icon(Icons.credit_card), title: const Text('Compra parcelada'), onTap: ()=>Navigator.pop(ctx,'installment')), ListTile(leading: const Icon(Icons.repeat), title: const Text('Despesa recorrente'), onTap: ()=>Navigator.pop(ctx,'recurring'))])));
    if (result == 'single') await _singleDialog();
    if (result == 'installment') await _installmentDialog();
    if (result == 'recurring') await _recurringDialog();
  }

  Future<void> _singleDialog() async {
    final desc=TextEditingController(), amount=TextEditingController(); bool income=false; String category='Outros'; DateTime date=DateTime.now(); String status='paid';
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD){ final cats=income?incomeCategories:expenseCategories; if(!cats.contains(category))category='Outros'; return AlertDialog(title:const Text('Nova movimentação'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor',prefixText:'R\$ ')),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Entrada'),value:income,onChanged:(v)=>setD(()=>{income=v;category='Outros';}),),DropdownButtonFormField<String>(value:category,isExpanded:true,items:cats.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setD(()=>category=v??category),decoration:const InputDecoration(labelText:'Categoria')),ListTile(contentPadding:EdgeInsets.zero,title:Text('Data: ${DateFormat('dd/MM/yyyy').format(date)}'),trailing:const Icon(Icons.calendar_month),onTap:()async{final d=await showDatePicker(context:ctx,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:date);if(d!=null)setD(()=>date=d);}),if(!income)DropdownButtonFormField<String>(value:status,items:const [DropdownMenuItem(value:'paid',child:Text('Já paga')),DropdownMenuItem(value:'pending',child:Text('Prevista'))],onChanged:(v)=>setD(()=>status=v??status),decoration:const InputDecoration(labelText:'Status'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('SALVAR'))]);}));
    final v=double.tryParse(amount.text.replaceAll(',','.')); if(ok!=true||desc.text.trim().isEmpty||v==null||v<=0)return;
    final d=DateFormat('yyyy-MM-dd').format(date); items.add(MoneyTransaction(id:DateTime.now().microsecondsSinceEpoch.toString(),date:d,description:desc.text.trim(),category:category,amount:v,income:income,paymentStatus:income?'paid':status,dueDate:d,paidDate:status=='paid'?d:null)); await _save(); if(mounted){setState((){});ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Movimentação salva com sucesso.')));}
  }

  Future<void> _installmentDialog() async {
    final desc=TextEditingController(), total=TextEditingController(), part=TextEditingController(), count=TextEditingController(text:'2'); String category='Outros'; DateTime first=DateTime.now(); bool byTotal=true;
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:const Text('Compra parcelada'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descrição da compra')),DropdownButtonFormField<String>(value:category,items:expenseCategories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setD(()=>category=v??category),decoration:const InputDecoration(labelText:'Categoria')),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Informar valor total'),value:byTotal,onChanged:(v)=>setD(()=>byTotal=v),),TextField(controller:byTotal?total:part,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:byTotal?'Valor total':'Valor de cada parcela',prefixText:'R\$ ')),TextField(controller:count,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantidade de parcelas')),ListTile(contentPadding:EdgeInsets.zero,title:Text('1ª parcela: ${DateFormat('dd/MM/yyyy').format(first)}'),trailing:const Icon(Icons.event),onTap:()async{final d=await showDatePicker(context:ctx,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:first);if(d!=null)setD(()=>first=d);})])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('CRIAR'))])));
    final n=int.tryParse(count.text); final base=double.tryParse((byTotal?total:part).text.replaceAll(',','.')); if(ok!=true||desc.text.trim().isEmpty||n==null||n<2||base==null||base<=0)return;
    final group=DateTime.now().microsecondsSinceEpoch.toString(); final totalValue=byTotal?base:base*n; final installment=byTotal?(totalValue/n):base; final generated=<MoneyTransaction>[];
    double allocated=0;
    for(var i=1;i<=n;i++){final d=DateTime(first.year,first.month+i-1,first.day); double value=i==n?totalValue-allocated:double.parse(installment.toStringAsFixed(2)); allocated+=value; final date=DateFormat('yyyy-MM-dd').format(d); final paid=d.isBefore(DateTime.now())||DateUtils.isSameDay(d,DateTime.now()); generated.add(MoneyTransaction(id:'$group-$i',date:date,description:desc.text.trim(),category:category,amount:value,income:false,paymentStatus:paid?'paid':'pending',isInstallment:true,installmentGroupId:group,totalInstallments:n,installmentNumber:i,totalAmount:totalValue,installmentAmount:value,dueDate:date,paidDate:paid?date:null));}
    items.addAll(generated); await _save(); if(mounted){setState((){});ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Compra parcelada criada com sucesso.')));}
  }

  Future<void> _recurringDialog() async {
    final desc=TextEditingController(), amount=TextEditingController(), months=TextEditingController(text:'12'); String category='Outros'; DateTime first=DateTime.now();
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:const Text('Despesa recorrente'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descrição')),DropdownButtonFormField<String>(value:category,items:expenseCategories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setD(()=>category=v??category),decoration:const InputDecoration(labelText:'Categoria')),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor por ocorrência',prefixText:'R\$ ')),TextField(controller:months,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Meses a gerar')),ListTile(contentPadding:EdgeInsets.zero,title:Text('Início: ${DateFormat('dd/MM/yyyy').format(first)}'),trailing:const Icon(Icons.event),onTap:()async{final d=await showDatePicker(context:ctx,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:first);if(d!=null)setD(()=>first=d);})])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('CRIAR'))])));
    final v=double.tryParse(amount.text.replaceAll(',','.')); final n=int.tryParse(months.text); if(ok!=true||desc.text.trim().isEmpty||v==null||v<=0||n==null||n<1)return;
    final group=DateTime.now().microsecondsSinceEpoch.toString(); final generated=<MoneyTransaction>[]; for(var i=0;i<n;i++){final d=DateTime(first.year,first.month+i,first.day); final date=DateFormat('yyyy-MM-dd').format(d); final paid=d.isBefore(DateTime.now())||DateUtils.isSameDay(d,DateTime.now()); generated.add(MoneyTransaction(id:'r-$group-$i',date:date,description:desc.text.trim(),category:category,amount:v,income:false,paymentStatus:paid?'paid':'pending',isRecurring:true,recurrenceGroupId:group,recurrenceFrequency:'monthly',recurrenceStartDate:DateFormat('yyyy-MM-dd').format(first),recurrenceEndDate:DateFormat('yyyy-MM-dd').format(DateTime(first.year,first.month+n-1,first.day)),dueDate:date,paidDate:paid?date:null));}
    items.addAll(generated); await _save(); if(mounted){setState((){});ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Despesa recorrente criada com sucesso.')));}
  }

  Future<void> _togglePaid(MoneyTransaction x) async { if(x.isCancelled)return; x.paymentStatus=x.isPaid?'pending':'paid'; x.paidDate=x.isPaid?null:DateFormat('yyyy-MM-dd').format(DateTime.now()); await _save(); if(mounted)setState((){}); }
  Future<void> _delete(MoneyTransaction x) async { String scope='one'; if(x.isInstallment||x.isRecurring){scope=await _scopeDialog('Excluir lançamento', 'Excluir somente este ou também os próximos?')??'cancel';} if(scope=='cancel')return; if(scope=='one')items.removeWhere((e)=>e.id==x.id); if(scope=='future')items.removeWhere((e)=>(x.isInstallment&&e.installmentGroupId==x.installmentGroupId&&e.installmentNumber>=x.installmentNumber)||(x.isRecurring&&e.recurrenceGroupId==x.recurrenceGroupId&&e.date.compareTo(x.date)>=0)); if(scope=='all')items.removeWhere((e)=>(x.isInstallment&&e.installmentGroupId==x.installmentGroupId)||(x.isRecurring&&e.recurrenceGroupId==x.recurrenceGroupId)); await _save(); if(mounted)setState((){}); }
  Future<String?> _scopeDialog(String title,String message) => showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:Text(title),content:Text(message),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,'cancel'),child:const Text('CANCELAR')),TextButton(onPressed:()=>Navigator.pop(ctx,'one'),child:const Text('SOMENTE ESTA')),TextButton(onPressed:()=>Navigator.pop(ctx,'future'),child:const Text('ESTA E PRÓXIMAS')),FilledButton(onPressed:()=>Navigator.pop(ctx,'all'),child:const Text('TODA A SÉRIE'))]));

  Future<void> _edit(MoneyTransaction x) async {
    final desc=TextEditingController(text:x.description), amount=TextEditingController(text:x.amount.toStringAsFixed(2)); DateTime date=DateTime.tryParse(x.date)??DateTime.now(); String category=x.category; String status=x.paymentStatus;
    final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setD)=>AlertDialog(title:const Text('Editar movimentação'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor',prefixText:'R\$ ')),DropdownButtonFormField<String>(value:(x.income?incomeCategories:expenseCategories).contains(category)?category:'Outros',items:(x.income?incomeCategories:expenseCategories).map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setD(()=>category=v??category),decoration:const InputDecoration(labelText:'Categoria')),DropdownButtonFormField<String>(value:status,items:const [DropdownMenuItem(value:'paid',child:Text('Pago/realizado')),DropdownMenuItem(value:'pending',child:Text('Previsto')),DropdownMenuItem(value:'cancelled',child:Text('Cancelado'))],onChanged:(v)=>setD(()=>status=v??status),decoration:const InputDecoration(labelText:'Status')),ListTile(contentPadding:EdgeInsets.zero,title:Text('Data: ${DateFormat('dd/MM/yyyy').format(date)}'),onTap:()async{final d=await showDatePicker(context:ctx,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:date);if(d!=null)setD(()=>date=d);})])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('SALVAR'))])));
    final v=double.tryParse(amount.text.replaceAll(',','.')); if(ok!=true||desc.text.trim().isEmpty||v==null||v<=0)return;
    String scope='one'; if(x.isInstallment||x.isRecurring) scope=await _scopeDialog('Aplicar alteração','Escolha o alcance da alteração.')??'cancel'; if(scope=='cancel')return;
    final targets=items.where((e){if(scope=='all')return x.isInstallment?e.installmentGroupId==x.installmentGroupId:x.isRecurring&&e.recurrenceGroupId==x.recurrenceGroupId;if(scope=='future')return x.isInstallment?e.installmentGroupId==x.installmentGroupId&&e.installmentNumber>=x.installmentNumber:x.isRecurring&&e.recurrenceGroupId==x.recurrenceGroupId&&e.date.compareTo(x.date)>=0;return e.id==x.id;}).toList();
    for(final t in targets){t.description=desc.text.trim();t.amount=v;t.category=category;t.paymentStatus=status;t.date=DateFormat('yyyy-MM-dd').format(scope=='one'?date:(DateTime.tryParse(t.date)??date));t.dueDate=t.date;t.paidDate=status=='paid'?DateFormat('yyyy-MM-dd').format(DateTime.now()):null;if(t.isInstallment)t.installmentAmount=v;}
    await _save();if(mounted){setState((){});ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Movimentação atualizada.')));}
  }

  List<Map<String,dynamic>> _forecasts() { final result=<Map<String,dynamic>>[]; for(var i=0;i<6;i++){final m=DateTime(month.year,month.month+i); final xs=items.where((x)=>_inMonth(x,m)&&!x.isCancelled); final inc=_sum(xs,true); final exp=_sum(xs,false); final inst=xs.where((x)=>x.isInstallment).fold(0.0,(s,x)=>s+x.amount); final rec=xs.where((x)=>x.isRecurring).fold(0.0,(s,x)=>s+x.amount); result.add({'month':m,'income':inc,'expenses':exp,'installments':inst,'recurring':rec,'committed':xs.where((x)=>!x.income&&!x.isPaid).fold(0.0,(s,x)=>s+x.amount),'balance':inc-exp,'ids':xs.map((x)=>x.id).toList()});} return result; }

  @override Widget build(BuildContext context){ if(loading)return const Center(child:CircularProgressIndicator()); final current=selected.toList()..sort((a,b)=>a.date.compareTo(b.date)); final income=_sum(current,true,onlyPaid:true), expense=_sum(current,false,onlyPaid:true), result=income-expense, next=DateTime(month.year,month.month+1); final committed=_committed(month); final projected=_forecastIncome(month)-_forecastExpenses(month); final byCat=<String,double>{}; for(final x in current.where((x)=>!x.income&&!x.isCancelled))byCat[x.category]=(byCat[x.category]??0)+x.amount;
    return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Financeiro',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:_add,icon:const Icon(Icons.add),label:const Text('Adicionar'))]),const SizedBox(height:8),AppCard(child:Row(children:[IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month-1)),icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat('MMMM yyyy','pt_BR').format(month),textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18))),IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month+1)),icon:const Icon(Icons.chevron_right))])),Row(children:[Expanded(child:_metric('Entradas realizadas',income)),Expanded(child:_metric('Despesas realizadas',expense))]),Row(children:[Expanded(child:_metric('Saldo atual',_actualBalance())),Expanded(child:_metric('Resultado do mês',result))]),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Compromissos e previsão',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('Comprometido no mês: ${_money(committed)}'),Text('Saldo projetado: ${_money(projected)}'),Text('Próximo mês comprometido: ${_money(_committed(next))}'),const SizedBox(height:6),Text('A previsão considera entradas e despesas cadastradas, parcelas e recorrências. Não representa o saldo bancário real.',style:Theme.of(context).textTheme.bodySmall)])),if(byCat.isNotEmpty)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Distribuição das despesas',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:10),...byCat.entries.map((e)=>Padding(padding:const EdgeInsets.symmetric(vertical:3),child:Row(children:[Expanded(child:Text(e.key)),Text(_money(e.value))])))])),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Previsão dos próximos meses',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),..._forecasts().map((f)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(DateFormat('MMM/yyyy','pt_BR').format(f['month'] as DateTime)),subtitle:Text('Entradas ${_money(f['income'] as double)} • Comprometido ${_money(f['committed'] as double)}'),trailing:Text(_money(f['balance'] as double),style:const TextStyle(fontWeight:FontWeight.bold)))])),Row(children:[ChoiceChip(label:const Text('Consolidada'),selected:view=='consolidada',onSelected:(_)=>setState(()=>view='consolidada')),const SizedBox(width:8),ChoiceChip(label:const Text('Previstas'),selected:view=='previstas',onSelected:(_)=>setState(()=>view='previstas'))]),const SizedBox(height:8),Text('Movimentações',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),if(current.isEmpty)const AppCard(child:Text('Nenhuma movimentação neste mês.')),...current.map((x)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,leading:CircleAvatar(child:Icon(x.income?Icons.arrow_downward:Icons.arrow_upward)),title:Text(x.description),subtitle:Text('${x.category} • ${DateFormat('dd/MM/yyyy').format(DateTime.tryParse(x.date)??DateTime.now())} • ${x.paymentStatus}${x.isInstallment?' • ${x.installmentNumber}/${x.totalInstallments}':''}${x.isRecurring?' • recorrente':''}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='edit')_edit(x);if(v=='delete')_delete(x);if(v=='pay')_togglePaid(x);},itemBuilder:(_)=>const [PopupMenuItem(value:'pay',child:Text('Marcar pago/previsto')),PopupMenuItem(value:'edit',child:Text('Editar')),PopupMenuItem(value:'delete',child:Text('Excluir'))]))))])); }
  Widget _metric(String label,double value)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_money(value),style:const TextStyle(fontWeight:FontWeight.bold)),Text(label,style:Theme.of(context).textTheme.bodySmall)]));
